// DSB IMPLEMENTATION sir-stale — READ ONLY.
var DAYS = 14, out = [];
var g = new GlideRecord('sn_si_incident'); g.addActiveQuery(); g.addEncodedQuery('sys_updated_onRELATIVELT@dayofweek@ago@' + DAYS); g.orderBy('sys_updated_on'); g.setLimit(300); g.query();
while (g.next()) out.push({number: g.getValue('number'), category: g.getDisplayValue('category'), state: g.getDisplayValue('state'), group: g.getDisplayValue('assignment_group'), updated: g.getValue('sys_updated_on')});
gs.print('=== DSB-IMPL sir-stale ===\n' + JSON.stringify({days: DAYS, count: out.length, incidents: out}, null, 2));
